// === Tab: mySketch ===
// handle color gradient
let colorChange = 0; // color gradient speed
let colorGradient = 1; // color gradient increment
let colorGradientDirection = true; // direction: from -> to or to -> from

let squareSize = 70; // middle square size

// Particle class
class Particle {
	// create a new particle
	constructor(e_positionX, e_positionY, e_color, e_size, e_speed){
			this.positionX		= e_positionX;
			this.positionY		= e_positionY;
			this.color				= e_color;
			this.size					= e_size;					// particle size
			this.speed				= e_speed;				// particle speed
			this.randomFactor	= random(0, 5);		// for random movement
			this.scale				= 1;							// scale up
	}

	// choose which move the particle can make
	setMoveType(move){
		this.moveType = move;
	}

	// move randomly on Y
	makeMoveRandomOnY(){
		// movement on Y has a random factor, depends on quadrant it started in
		if(this.positionY <= 0) {
			this.positionY -= this.randomFactor * this.speed;
		} else {
			this.positionY += this.randomFactor * this.speed;
		}

		// movement on X is linear, depends on quadrant it started in
		if(this.positionX <= 0){
			this.positionX -= this.speed;
		} else {
			this.positionX += this.speed;
		}

		this._updateScale(); // increase scaling/particle size
	}

	// move randomly on X
	makeMoveRandomOnX(){
		// movement on Y is linear, depends on quadrant it started in
		if(this.positionY <= 0){
			this.positionY -= this.speed;
		} else {
			this.positionY += this.speed;
		}

		// movement on X has a random factor, depends on quadrant it started in
		if(this.positionX <= 0){
			this.positionX -= this.randomFactor * this.speed;
		} else {
			this.positionX += this.randomFactor * this.speed;
		}

		this._updateScale(); // increase scaling/particle size
	}

	// update scaling
	_updateScale(){
		this.scale += 0.05; // increase scaling/particle size
	}

	// check if particle still needs to be displayed aka kept alive
	isAlive(){
		// limit after which the particle disappears
		// larger than canvas size to make sure bubble is completly out of sight
		const limit = width;

		// must take scaling into consideration
		const X = Math.trunc(this.positionX * this.scale);
		const Y = Math.trunc(this.positionY * this.scale);

		// check lifespan
		return !(X <= -limit || X >= limit || Y <= -limit || Y >= limit);
	}
}

// particles to draw
let particlesArray = [];

function setup() {
	createCanvas(windowWidth, screen.availHeight);
	frameRate(30);
}

function draw() {
	translate(115, -95);
	// we'll use color gradients based on lerp coloring
	handleColorGradient();
	let colorFrom			= color(255, 250, 110);
	let colorTo				= color(255, 84, 102);
	let frameColor		= lerpColor(colorFrom, colorTo, colorGradient/100);

	// draw background: fixed squares and noisy vertical line
	drawBackground(frameColor);

	// the rest is about handling particles...
	// create new particles
	for(let i = 0; i < 4; i++) {
		// randomly create new particles starting from the middle square
		let newX				= random(-squareSize/2, squareSize/2);
		let newY				= random(-squareSize/2, squareSize/2);
		let newSize			= random (1, 5*i + 5);
		let newSpeed		= random(1, 0.5*i);

		// reset alpha (transparency) of color
		frameColor.setAlpha(255);

		// create new Particle
		let newParticle	= new Particle(newX, newY, frameColor, newSize, newSpeed);
		newParticle.setMoveType(i % 2);

		// add new particle to array
		particlesArray.push(newParticle);
	}

	// remove dead particles
	let i = particlesArray.length - 1;
	while(i >= 0){
		let currentParticle = particlesArray[i];	
		if(!currentParticle.isAlive()){
			particlesArray.splice(i, 1);
		} else {
			i--;
		}
	}

	// move existing particles
	for(let i = 0; i < particlesArray.length; i++){
		var currentParticle = particlesArray[i];
		// move depending on move type the particle can do
		if(currentParticle.moveType === 1){
			// particle will have a random component for movement on Y
			currentParticle.makeMoveRandomOnY();
		} else {
			// particle will have a random component for movement on X
			currentParticle.makeMoveRandomOnX();
		}
	}

	// draw particles, now that the array is clean and ready
	for(let i = 0; i < particlesArray.length; i++){
		var currentParticle = particlesArray[i];

		push(); // context start

		fill(currentParticle.color); // use color the particle started with
		scale(currentParticle.scale); // scale over time/towards border

		// draw the particle with its current attribute values
		circle(currentParticle.positionX, currentParticle.positionY, currentParticle.size);

		pop(); // context end
	}
}

// draws the background
function drawBackground(frameColor){
	background(20);

	// base shapes (background)
	fill(40);

	noStroke();
	translate(400, 450); 
}

// handle the color gradient for nice transitions
function handleColorGradient(){
	// change color gradient direction when reaching extreme values
	if(colorGradient === 100) colorGradientDirection = false;
	if(colorGradient === 0) colorGradientDirection = true;

	if(colorGradientDirection){ // for "pulsating" color gradients
		if(colorGradient < 100) colorGradient++; // for lerpColor interpolation value increasing
	} else {
		if(colorGradient > 0) colorGradient--; // for lerpColor interpolation value decreasing
	}
}

function mousePressed(){
  save('pix.jpg');
}

